insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_37_v1'
from (values
('127.224.d.1.A',3,'An animator pitching a short film to a client keeps her emails free of spelling errors and organizes her ideas clearly. She is applying skills from which subject?','["English language arts", "Chemistry", "Physical education", "Geometry only"]'::jsonb,0,'Clear reading, writing, and speaking are English language arts skills used in every workplace.','original'),
('127.224.d.1.A',4,'Which habit shows an animation student consistently using English language arts skills on the job?','["Skipping the script and improvising on set", "Proofreading a script before sending it to a client", "Using slang in every client email", "Sending messages in all capital letters"]'::jsonb,1,'Careful reading and writing keep professional communication clear.','original'),
('127.224.d.1.B',3,'An animation studio charges $40 per hour. A freelancer works 6 hours on a short clip. What does she put on the invoice?','["$200", "$46", "$240", "$34"]'::jsonb,2,'40 x 6 = 240.','original'),
('127.224.d.1.B',4,'A 12-second animation plays at 24 frames per second. How many frames must be drawn or rendered?','["144", "36", "24", "288"]'::jsonb,3,'12 x 24 = 288 frames.','original'),
('127.224.d.2.A',3,'An animator explains a storyboard to a group of kindergarten students. Which choice best adapts the language to the audience?','["Simple words and short sentences", "Text full of abbreviations", "Dense industry jargon", "A long technical report"]'::jsonb,0,'Language should match the audience''s age and background.','original'),
('127.224.d.2.A',4,'A studio writes a casual text to a coworker and a formal proposal to a client. What are they adjusting?','["The monitor brightness", "Structure and style for the situation", "The file compression", "The animation frame rate"]'::jsonb,1,'Style and structure change with purpose and audience.','original'),
('127.224.d.2.B',3,'Before a team meeting, an animator puts her notes in order from most to least important. This is an example of:','["erasing information", "hiding information", "organizing information", "guessing at facts"]'::jsonb,2,'Organizing written and oral information makes it easier to share.','original'),
('127.224.d.2.B',4,'Which step comes first when formulating a clear oral explanation of an animation concept?','["Start talking and see what happens", "Add effects to every slide", "Read your slides aloud word for word", "Decide the main point you want to make"]'::jsonb,3,'A clear main point guides how information is arranged.','original'),
('127.224.d.2.C',3,'A studio tracks how many people watched each episode and shows the results in a bar graph. This is communicating:','["data with a visual", "opinions without proof", "rumors", "only sound"]'::jsonb,0,'Graphs help people interpret and share data.','original'),
('127.224.d.2.C',4,'An animator tells the director that view counts rose 20% after a trailer. What makes this effective?','["It repeats the same point", "It communicates data in a clear, specific way", "It uses vague words only", "It avoids numbers"]'::jsonb,1,'Specific, accurate data communicates results clearly.','original'),
('127.224.d.2.D',3,'A student pitches a cartoon idea to classmates using slides and a short demo. This is a:','["private diary entry", "blank page", "formal presentation", "random doodle"]'::jsonb,2,'A planned talk with slides is a formal presentation.','original'),
('127.224.d.2.D',4,'Which best describes an informal presentation in an animation class?','["Mailing a signed contract", "Filing a legal report", "Delivering a scripted keynote in a theater", "Showing a rough clip to a partner and chatting about it"]'::jsonb,3,'Informal presentations are relaxed and conversational.','original'),
('127.224.d.2.E',3,'A client describes a character change. The animator nods, takes notes, and repeats the request back. These are examples of:','["active listening", "avoiding eye contact", "daydreaming", "interrupting"]'::jsonb,0,'Active listening confirms understanding of what was said.','original'),
('127.224.d.2.E',4,'After a client gives vague feedback, which response best clarifies the information?','["Redo the whole film", "Ask which scene and what change is wanted", "Say nothing and guess", "Change the subject"]'::jsonb,1,'Clarifying questions prevent mistakes and rework.','original'),
('127.224.d.2.F',3,'An animation team has members from many cultures and backgrounds. A good teammate will:','["talk over quiet coworkers", "ignore different opinions", "listen respectfully to each person", "only work with friends"]'::jsonb,2,'Respecting diverse people improves collaboration.','original'),
('127.224.d.2.F',4,'A coworker speaks English as a second language and pauses often. What is a respectful response?','["Finish all of their sentences", "Roll your eyes", "Switch to another coworker", "Be patient and speak clearly without rushing them"]'::jsonb,3,'Patience and clear speech show respect for diverse speakers.','original'),
('127.224.d.2.G',3,'A studio replies politely and quickly to a customer who is unhappy with a delivery. This shows:','["public relations skills", "poor planning", "framing skills", "rendering skills"]'::jsonb,0,'Courteous responses protect the studio''s reputation.','original'),
('127.224.d.2.G',4,'An animation company posts friendly updates about new projects and answers viewer comments. They are building:','["a secret contract", "a positive public image", "a lower frame rate", "a hidden budget"]'::jsonb,1,'Public relations builds goodwill with customers.','original'),
('127.224.d.3.A',3,'A team gathers viewer ratings, compares them, and decides which short to expand into a series. This uses:','["random choice", "guesswork", "critical-thinking skills", "luck"]'::jsonb,2,'Gathering and interpreting data supports good decisions.','original'),
('127.224.d.3.A',4,'Which action best shows critical thinking when an animation keeps stuttering?','["Blame the teammate", "Restart and hope it fixes itself", "Delete the project", "Test possible causes one at a time and compare results"]'::jsonb,3,'Systematic testing identifies the true cause.','original'),
('127.224.d.3.B',3,'Four animators disagree about a scene''s look. Which approach helps the group decide?','["Share ideas, discuss pros and cons, then agree", "Avoid the topic", "Let the loudest person win", "Flip a coin every time"]'::jsonb,0,'Interpersonal skills help groups solve problems together.','original'),
('127.224.d.3.B',4,'A team uses brainstorming and then votes on the best idea. This is an example of:','["ignoring ideas", "group decision making", "working alone", "delaying work"]'::jsonb,1,'Groups combine ideas and then decide together.','original'),
('127.224.d.4.A',3,'Which tool is best for sending a quick written update to a teammate who works in another city?','["A paper airplane", "A sketchbook", "Email", "A tripod"]'::jsonb,2,'Email allows quick written communication at a distance.','original'),
('127.224.d.4.A',4,'An animator uses a word processor, email, and the Internet. These are all:','["paint brushes", "storyboard pins", "lighting kits", "technology applications"]'::jsonb,3,'They are software tools that support work tasks.','original'),
('127.224.d.4.B',3,'Putting animation files into clearly named folders so they are easy to find is called:','["file management", "file wasting", "file deletion", "file hiding"]'::jsonb,0,'Good file management saves time.','original'),
('127.224.d.4.B',4,'Which naming habit makes version tracking easiest for an animation project?','["Naming every file Final", "Adding a date or version number to each file name", "Saving everything to the desktop", "Using random symbols"]'::jsonb,1,'Version numbers show which file is newest.','original'),
('127.224.d.5.A',3,'Hand-drawn cels were used in early animation. Today most studios mostly use:','["only clay", "no equipment", "computer-based tools", "only paper cels"]'::jsonb,2,'Animation moved from hand-drawn film to digital production.','original'),
('127.224.d.5.A',4,'Which statement best summarizes the evolution of animation?','["It stopped being made", "It began with 3-D computers", "It has not changed", "It moved from hand-drawn frames to digital 2-D and 3-D tools"]'::jsonb,3,'Technology expanded the ways animation is produced.','original'),
('127.224.d.5.B',3,'Streaming platforms and short social video are trends that:','["give animators new ways to reach viewers", "remove the need for stories", "ban color", "end all animation careers"]'::jsonb,0,'Industry trends shape where and how animation is seen.','original'),
('127.224.d.5.B',4,'Studios now use real-time game engines for some animation. This trend lets teams:','["avoid planning", "preview scenes instantly while working", "delete scripts", "skip sound"]'::jsonb,1,'Real-time rendering speeds up review.','original'),
('127.224.d.6.A',3,'Before using a heavy light stand, a student checks that it is stable. This is following:','["a dress code only", "a style guide", "workplace safety rules", "a sales quota"]'::jsonb,2,'Safety rules prevent injuries and damage.','original'),
('127.224.d.6.A',4,'Which habit is part of consistently following studio safety regulations?','["Plugging many devices into one outlet", "Ignoring posted signs", "Leaving cables across the floor", "Keeping cables taped down and walkways clear"]'::jsonb,3,'Clear walkways prevent trips and falls.','original'),
('127.224.d.6.B',3,'A coworker notices a frayed power cord on a computer. What should they do?','["Report it and stop using it", "Tape it quickly and ignore it", "Hide it behind a desk", "Keep using it"]'::jsonb,0,'Frayed cords are shock and fire hazards.','original'),
('127.224.d.6.B',4,'Sitting for hours at a drawing tablet can cause strain. Which step helps resolve this concern?','["Work without any breaks", "Take regular breaks and adjust the chair", "Use a smaller desk", "Raise the screen brightness"]'::jsonb,1,'Ergonomic changes reduce strain injuries.','original'),
('127.224.d.6.C',3,'A fire alarm sounds in the studio. What should employees do?','["Keep working", "Record the alarm", "Leave by the posted exit route", "Hide in a closet"]'::jsonb,2,'Following emergency procedures keeps people safe.','original'),
('127.224.d.6.C',4,'Why are evacuation maps posted near studio doors?','["To list holidays", "To advertise software", "To decorate the wall", "To show the quickest safe route out"]'::jsonb,3,'Maps support fast, safe exits in an emergency.','original'),
('127.224.d.7.A',3,'A lead animator sets a goal, assigns tasks, and checks progress. This shows:','["leadership skills", "avoidance", "carelessness", "only artistic skill"]'::jsonb,0,'Leaders set goals and guide the team to reach them.','original'),
('127.224.d.7.A',4,'Which action shows leadership when a project falls behind schedule?','["Blame one animator", "Analyze the problem and adjust tasks with the team", "Stop communicating", "Cancel the project quietly"]'::jsonb,1,'Leaders analyze and respond to obstacles.','original'),
('127.224.d.7.B',3,'Two teammates disagree about a character''s design. A good teammate will:','["quit the team", "refuse to talk", "listen to both sides and look for a compromise", "complain to clients"]'::jsonb,2,'Conflict management supports collective goals.','original'),
('127.224.d.7.B',4,'Which phrase supports teamwork during a disagreement?','["Do it my way", "You never listen", "That idea is dumb", "Let''s list what each of us needs"]'::jsonb,3,'Respectful wording keeps teams focused on the goal.','original'),
('127.224.d.7.C',3,'Giving a coworker helpful feedback and encouragement builds:','["good working relationships", "confusion", "tension", "distance"]'::jsonb,0,'Constructive support builds trust.','original'),
('127.224.d.7.C',4,'Which comment is constructive feedback on a rough animation?','["This is awful", "The timing is good; try slowing the jump slightly", "Why bother", "I could do better"]'::jsonb,1,'Specific, kind feedback helps a coworker improve.','original'),
('127.224.d.7.D',3,'Before a production meeting, the animator writes down what the team needs to decide. She is:','["skipping tasks", "wasting time", "preparing goals for the meeting", "avoiding the meeting"]'::jsonb,2,'Preparation makes meetings productive.','original'),
('127.224.d.7.D',4,'Which item belongs on a meeting agenda?','["Jokes only", "Gossip", "Lunch orders only", "Topics, time limits, and desired outcomes"]'::jsonb,3,'An agenda keeps a meeting on track.','original'),
('127.224.d.7.E',3,'During a work meeting, a good participant will:','["stay on topic and take notes", "scroll social media", "interrupt others", "leave without saying why"]'::jsonb,0,'Focused participation helps accomplish work tasks.','original'),
('127.224.d.7.E',4,'After a meeting ends, which step helps ensure tasks get done?','["Wait a month", "Send notes listing who will do what and by when", "Say nothing", "Delete the agenda"]'::jsonb,1,'Written follow-up keeps everyone accountable.','original'),
('127.224.d.7.F',3,'An experienced animator teaches a new intern how to use the software. This is:','["delaying", "copying", "mentoring", "competing"]'::jsonb,2,'Mentors teach and inspire others.','original'),
('127.224.d.7.F',4,'What makes a good mentor?','["Criticizing harshly", "Avoiding questions", "Keeping secrets", "Patience and willingness to share knowledge"]'::jsonb,3,'Good mentors support growth in others.','original'),
('127.224.d.8.A',3,'An animator borrows a color palette from a classmate''s work. What is the ethical thing to do?','["Give credit to the classmate", "Say it was entirely your idea", "Remove their name from the file", "Hide the source"]'::jsonb,0,'Ethical conduct includes crediting ideas.','original'),
('127.224.d.8.A',4,'Which action best shows ethical conduct in a group animation project?','["Taking credit for the group''s work", "Listing everyone who contributed in the credits", "Leaving collaborators off", "Copying a rival''s file"]'::jsonb,1,'Proper credit respects each person''s contribution.','original'),
('127.224.d.8.B',4,'A teacher uses a short clip of a film in class to explain a technique. This may fall under:','["piracy", "trademark loss", "fair use", "free ownership"]'::jsonb,2,'Fair use allows limited use for teaching, with conditions.','original'),
('127.224.d.8.C',3,'Before morphing a photograph into a new animation, an artist should:','["assume anything online is free", "remove the photographer''s name", "sell it immediately", "make sure she has permission or rights to use it"]'::jsonb,3,'Respecting intellectual property includes getting permission.','original'),
('127.224.d.8.C',4,'An animator edits and blends someone else''s artwork into a new piece. To respect intellectual property, she should:','["obtain permission or use properly licensed material", "crop out the signature", "post it without a source", "claim it as completely her own"]'::jsonb,0,'Changing a work does not remove the creator''s rights.','original'),
('127.224.d.8.D',3,'A school''s acceptable use policy says students may not install unapproved software. A student should:','["ask a friend to do it", "follow the policy", "hide it", "install it anyway"]'::jsonb,1,'Acceptable use policies set rules for technology.','original'),
('127.224.d.8.D',4,'Which is proper etiquette when using a shared studio network?','["Share your password", "Change other users'' files", "Avoid downloading huge files that slow others down", "Stream movies all day"]'::jsonb,2,'Etiquette includes thoughtful use of shared resources.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_37_v1'
from (values
('127.224.d.8.E',3,'Cartoons and animated films can influence what viewers think about topics and people. This shows animation''s:','["lack of effect", "only cost", "only color", "impact on society"]'::jsonb,3,'Media influences culture and attitudes.','original'),
('127.224.d.8.E',4,'The animation industry affects society by providing entertainment, education, and:','["jobs and economic activity", "no income", "less communication", "only losses"]'::jsonb,0,'The industry employs people and informs audiences.','original'),
('127.224.d.9.A',3,'A career portfolio can include:','["a grocery list", "work samples, a resume, and certificates", "only a lunch menu", "unrelated photos"]'::jsonb,1,'A portfolio documents skills and experience.','original'),
('127.224.d.9.A',4,'Why should an animation student keep their career portfolio updated?','["To hide past work", "To avoid interviews", "To show new work and skills to future employers", "To save printing costs"]'::jsonb,2,'A current portfolio reflects growth.','original'),
('127.224.d.9.B',3,'Two job offers pay differently and offer different benefits. A smart job seeker will:','["accept the first one without reading", "pick at random", "ignore the details", "compare pay, benefits, and growth chances"]'::jsonb,3,'Comparing offers supports a good choice.','original'),
('127.224.d.9.B',4,'Which factor should be weighed when evaluating an employment opportunity?','["Opportunities for advancement", "The weather forecast", "The color of the building", "The manager''s favorite song"]'::jsonb,0,'Growth potential matters for a career.','original'),
('127.224.d.9.C',3,'Attending a career fair to meet industry professionals is an example of:','["avoiding work", "professional networking", "gaming", "shopping"]'::jsonb,1,'Networking builds career connections.','original'),
('127.224.d.9.C',4,'Which action helps build a professional network?','["Never reply to messages", "Throw away business cards", "Follow up with a thank-you message after meeting someone", "Avoid industry events"]'::jsonb,2,'Follow-up keeps connections active.','original'),
('127.224.d.9.D',3,'Starting your own animation business instead of working for a studio is:','["retirement", "unemployment", "apprenticeship only", "entrepreneurship"]'::jsonb,3,'Entrepreneurs create and run their own businesses.','original'),
('127.224.d.9.D',4,'One challenge of being a self-employed animator is:','["finding your own clients and managing finances", "receiving a guaranteed paycheck", "never needing contracts", "having no work"]'::jsonb,0,'Entrepreneurs handle sales and money themselves.','original'),
('127.224.d.10.A',3,'Breaking a big animation project into smaller tasks with due dates is:','["procrastination", "planning and time management", "guessing", "avoidance"]'::jsonb,1,'Planning helps complete work on time.','original'),
('127.224.d.10.A',4,'Which approach best helps a team meet a deadline?','["Wait until the last day", "Work without a schedule", "Set milestones and check progress regularly", "Skip planning"]'::jsonb,2,'Milestones keep work on track.','original'),
('127.224.d.10.B',3,'Using a calendar app to remind you about deadlines is using technology to:','["delay work", "hide tasks", "lose files", "enhance productivity"]'::jsonb,3,'Technology can help organize time.','original'),
('127.224.d.10.B',4,'A shared task board lets a team see who is doing what. This improves:','["coordination", "cost", "confusion", "secrecy"]'::jsonb,0,'Visible tasks reduce overlap and missed work.','original'),
('127.224.d.11.A',3,'At the first meeting, an animator asks a client what the film is for and who will watch it. She is:','["editing audio", "identifying client needs", "testing hardware", "selling a product"]'::jsonb,1,'Questions reveal what the client wants.','original'),
('127.224.d.11.A',4,'Which question best helps determine a client''s needs for a short animation?','["What did you eat today?", "Do you like Mondays?", "What message and audience do you have in mind?", "What is your favorite color?"]'::jsonb,2,'Purpose and audience guide the project.','original'),
('127.224.d.11.B',3,'A production proposal given to a client for approval often includes:','["a personal playlist", "unrelated news", "private diary pages", "a timeline and a cost estimate"]'::jsonb,3,'Proposals state scope, schedule, and cost.','original'),
('127.224.d.11.B',4,'Why get client approval of a proposal before starting production?','["To confirm both sides agree on the plan", "To delay the project", "To raise the price", "To skip the contract"]'::jsonb,0,'Approval prevents misunderstandings.','original'),
('127.224.d.12.A',3,'Listing the actors, camera operators, and locations needed for a shoot is identifying:','["poster sizes", "production requirements", "viewer ratings", "paint colors"]'::jsonb,1,'Planning requires knowing cast, crew, equipment, and place.','original'),
('127.224.d.12.A',4,'A voice-over recording requires which equipment?','["A paint roller", "A drill", "A microphone and a quiet space", "A projector screen only"]'::jsonb,2,'Clean audio needs the right mic and environment.','original'),
('127.224.d.12.B',3,'A production budget should consider the cost of:','["vacations", "pet food", "unrelated gifts", "crew, equipment, and locations"]'::jsonb,3,'Budgets account for the main production expenses.','original'),
('127.224.d.12.B',4,'If rental equipment costs more than planned, the producer should:','["adjust the budget or find lower-cost options", "hide the invoice", "ignore the overage", "stop paying the crew"]'::jsonb,0,'Good budgeting responds to changing costs.','original'),
('127.224.d.12.C',3,'A storyboard shows a project''s scenes as:','["a list of prices", "a sequence of drawn panels", "a paycheck", "an audio mix"]'::jsonb,1,'Storyboards plan visuals shot by shot.','original'),
('127.224.d.12.C',4,'Why is a script analyzed alongside the storyboard?','["To lower the volume", "To erase scenes", "To make sure visuals and dialogue match", "To change fonts"]'::jsonb,2,'Both documents must support the same story.','original'),
('127.224.d.12.D',3,'Choosing who will be the director, animator, and sound designer is:','["buying software", "painting sets", "picking lunch", "assigning team roles"]'::jsonb,3,'Clear roles make production run smoothly.','original'),
('127.224.d.12.D',4,'Why define team roles before production starts?','["So each person knows their responsibilities", "So tasks overlap", "So no one works", "So the budget disappears"]'::jsonb,0,'Defined roles reduce confusion.','original'),
('127.224.d.13.A',3,'Before production, an animator meets with the client to explain how the work will be done. This is:','["cancelling the job", "presenting production strategies", "avoiding the client", "closing the studio"]'::jsonb,1,'Clients should understand the plan.','original'),
('127.224.d.13.A',4,'What should an animator do when a client suggests a change in the middle of production?','["Agree with no questions", "Stop responding", "Discuss how it affects time and cost", "Ignore the suggestion"]'::jsonb,2,'Changes affect schedule and budget.','original'),
('127.224.d.13.B',3,'Filming scenes in an order that fits the schedule and then assembling them is a:','["blank timeline", "single photo", "random pile of clips", "sequence of production events"]'::jsonb,3,'Production follows a planned sequence.','original'),
('127.224.d.13.B',4,'What does a coherent sequence of production events help prevent?','["Delays and rework", "Color", "Sound", "Storytelling"]'::jsonb,0,'Order and planning save time.','original'),
('127.224.d.13.C',3,'Using the correct microphone, lights, and crew produces:','["a messy set", "a quality production", "unsafe work", "lost files"]'::jsonb,1,'Proper equipment and crew improve results.','original'),
('127.224.d.13.C',4,'Why is trained crew important during a shoot?','["They avoid the script", "They replace the client", "They operate equipment correctly and safely", "They delete takes"]'::jsonb,2,'Skilled crew improve both quality and safety.','original'),
('127.224.d.13.D',3,'A crew member respectfully listens to a teammate who is stressed on set. This shows:','["competition", "rudeness", "avoidance", "teamwork and sensitivity"]'::jsonb,3,'Interpersonal skills keep the crew working well.','original'),
('127.224.d.13.D',4,'Which response shows good interpersonal skills when a deadline is close?','["Stay calm and ask how you can help", "Blame the intern", "Snap at coworkers", "Leave the set"]'::jsonb,0,'Calm support helps the team under pressure.','original'),
('127.224.d.13.E',3,'Cutting clips together, adding transitions, and fixing audio uses:','["a printing press", "an editing system", "a thermostat", "a saw"]'::jsonb,1,'Editing software assembles footage into a finished piece.','original'),
('127.224.d.13.E',4,'Which is an appropriate use of an editing system?','["Charging a phone", "Cooking dinner", "Trimming clips on a timeline", "Typing a taxes form only"]'::jsonb,2,'Editing involves arranging and trimming clips.','original'),
('127.224.d.13.F',3,'A director chooses the camera angle, lighting, and sound for a scene. She is making decisions about:','["her lunch", "the weather", "only the budget", "each element of production"]'::jsonb,3,'Each element influences the final product.','original'),
('127.224.d.13.F',4,'Why should decisions about lighting and sound be made together?','["They both affect how the audience feels about the scene", "They only affect the credits", "They are unrelated", "They cost nothing"]'::jsonb,0,'Elements work together to create mood.','original'),
('127.224.d.14.A',3,'A video will not play on a client''s older device. The animator checks the file type and resolution. She is solving a:','["scheduling issue", "compatibility issue", "marketing issue", "color issue"]'::jsonb,1,'Compatibility problems arise when formats are unsupported.','original'),
('127.224.d.14.A',4,'Which step helps avoid compatibility problems on different devices?','["Rename the file extension", "Skip testing", "Export the file in a widely supported format", "Use a rare file type"]'::jsonb,2,'Common formats play on most devices.','original'),
('127.224.d.14.B',3,'Making a video file smaller so it uploads faster uses:','["louder sound", "bigger frames", "more pixels", "compression"]'::jsonb,3,'Compression reduces file size.','original'),
('127.224.d.14.B',4,'H.264 and MPEG are examples of:','["compression standards", "microphones", "fonts", "cameras"]'::jsonb,0,'They are video encoding standards.','original'),
('127.224.d.14.C',3,'A cartoon for mobile phones is delivered in a size and format that fit small screens. The animator researched:','["coffee brands", "delivery formats for the audience", "office furniture", "printer ink"]'::jsonb,1,'Delivery format depends on the target audience.','original'),
('127.224.d.14.C',4,'A film is shown in a movie theater and also posted online. Why might two formats be needed?','["Theaters accept no files", "Online sites need no files", "Each platform has different technical needs", "They are identical"]'::jsonb,2,'Platforms differ in resolution and file types.','original'),
('127.224.d.14.D',3,'A client wants to share an animation on social media and in a school. The animator should:','["say nothing", "refuse to help", "pick one at random", "recommend the best delivery options for each"]'::jsonb,3,'Advising clients is part of professional service.','original'),
('127.224.d.14.D',4,'Which detail should an animator consider when advising a client on delivery?','["Where and how the audience will watch it", "The studio''s wall color", "Which animator likes pizza", "The client''s shoe size"]'::jsonb,0,'Viewing context decides the best format.','original'),
('127.224.d.15.A',3,'A freelance animator creates a short demo reel and a website to attract clients. This is:','["time off", "self-promotion", "budget cutting", "a legal filing"]'::jsonb,1,'Freelancers market themselves.','original'),
('127.224.d.15.A',4,'Which is a standard self-promotion technique for a freelancer?','["Changing careers each week", "Hiding all work", "Posting a portfolio and sharing it with potential clients", "Declining all inquiries"]'::jsonb,2,'Visible work attracts business.','original'),
('127.224.d.15.B',3,'A freelancer sends a client a document listing the work, price, and due date. This is a:','["map", "song lyric", "lullaby", "proposal"]'::jsonb,3,'A proposal outlines the services and costs.','original'),
('127.224.d.15.B',4,'If an invoice has not been paid by its due date, a freelancer follows standard:','["collection practices", "storytelling", "drawing", "design"]'::jsonb,0,'Collection practices help get paid on time.','original'),
('127.224.d.15.C',3,'Before starting a freelance business, an animator learns about licenses, taxes, and insurance. This is researching:','["movie reviews", "start-up practices", "retirement homes", "paint colors"]'::jsonb,1,'Start-up research reduces surprises.','original'),
('127.224.d.15.C',4,'Which resource would help a new freelancer learn about starting a business?','["A random meme page", "A toy store", "A small business development organization", "A cooking show"]'::jsonb,2,'Business organizations give reliable guidance.','original'),
('127.224.d.15.D',3,'Invoice software, cloud storage, and project trackers are:','["art supplies", "building tools", "gym equipment", "technology applications for freelancers"]'::jsonb,3,'Freelancers use software to run their business.','original'),
('127.224.d.15.D',4,'A freelancer wants clients to review drafts remotely. Which technology fits best?','["A cloud file-sharing service", "A fax from 1990", "A typewriter", "A paper mailbox"]'::jsonb,0,'Cloud tools make review easy.','original'),
('127.224.d.16.A',3,'A job seeker researches which studios hire animators and what skills they need. This is identifying:','["parking spots", "types and requirements of employers", "holiday dates", "lunch places"]'::jsonb,1,'Understanding employers helps target applications.','original')
